(511,'商品管理',1,'com.ruoyi.web.controller.admin.AdminProductController.add()','POST',1,'admin','研发部门','/api/v1/admin/products','127.0.0.1','内网IP','{\"categoryId\":9,\"description\":\"<p>专为宠物打结毛发设计，梳齿圆润顺滑，开结同时减少扯痛感，呵护皮肤表层。人体工学握柄，久梳不累；轻松去除浮毛与死结，促进皮毛血液循环，让被毛恢复柔顺光泽。日常梳理必备，省心省力。</p><p><br></p><p><br></p>\",\"id\":4,\"pointsPrice\":1,\"productImages\":\"[\\\"/profile/upload/2026/08/20/product7_20260820134533A010.png\\\"]\",\"productName\":\"毛梳\",\"status\":\"1\",\"stock\":5} ','{\"msg\":\"操作成功\",\"code\":200}',0,NULL,'2026-08-20 05:45:37',24),
